"""Compare the port with outputs from original GenroPy, never regenerated by CI."""
import json
from pathlib import Path

import pytest

from asqueel._legacy_sql import FieldReferences, split_sql, template_replace


ORACLE = json.loads((Path(__file__).parents[1] / 'oracles/legacy_sql_text.json').read_text())
RECORDS = ORACLE['records']


@pytest.mark.parametrize('record', [r for r in RECORDS if r['kind'] != 'discover'],
                         ids=lambda r: f"{r['kind']}:{r['name']}:{r.get('separator', r.get('safe'))}")
def test_original_text_contract(record):
    def run():
        if record['kind'] == 'split':
            return split_sql(record['text'], record['separator'])
        return template_replace(record['text'], record['symbols'], safe=record['safe'])

    expected = record['legacy']
    if 'error' in expected:
        with pytest.raises(Exception) as caught:
            run()
        assert type(caught.value).__name__ == expected['error']
    else:
        assert run() == expected['value']


def test_original_discovery_order_and_maps():
    previous = None
    for record in RECORDS:
        if record['kind'] != 'discover':
            continue
        name = record['name'].split(':')[0]
        if name != previous:
            references = FieldReferences()
            previous = name
        assert references.discover(record['text']) == record['legacy']['value']
        assert references.paths == record['legacy']['paths']
